document.querySelectorAll('[data-lab="L07-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const fold=root.querySelector('[data-fold]'),rotation=root.querySelector('[data-rotation]'),mass=root.querySelector('[data-mass]'),en=root.dataset.lang==='en',ns='http://www.w3.org/2000/svg';function draw(){const t=+fold.value*Math.PI/180,p=+rotation.value*Math.PI/180,c=Math.cos(t),s=Math.sin(t),raw=[[-2*c,0],[-c,s],[0,0],[c,s],[2*c,0]],pts=raw.map(([x,y])=>[x*Math.cos(p)-y*Math.sin(p),x*Math.sin(p)+y*Math.cos(p)]),w=[1,1,1,1,mass.value==='heavy'?4:1],total=w.reduce((a,b)=>a+b,0),cm=[0,1].map(k=>pts.reduce((sum,v,i)=>sum+w[i]*v[k],0)/total),rg=Math.sqrt(pts.reduce((sum,v,i)=>sum+w[i]*((v[0]-cm[0])**2+(v[1]-cm[1])**2),0)/total),end=[pts[4][0]-pts[0][0],pts[4][1]-pts[0][1]],re=Math.hypot(...end),map=([x,y])=>[450+95*x,260-95*y];root.querySelector('[data-fold-value]').textContent=fold.value;root.querySelector('[data-rotation-value]').textContent=rotation.value;root.querySelector('[data-chain]').setAttribute('points',pts.map(v=>map(v).join(',')).join(' '));const group=root.querySelector('[data-points]');group.replaceChildren();pts.forEach((v,i)=>{const [x,y]=map(v),circle=document.createElementNS(ns,'circle');circle.setAttribute('cx',x);circle.setAttribute('cy',y);circle.setAttribute('r',w[i]===4?14:9);circle.setAttribute('fill',i===0||i===4?'#c16b3d':'#167d84');group.append(circle);const label=document.createElementNS(ns,'text');label.setAttribute('x',x+13);label.setAttribute('y',i===2?y+29:y-13);label.setAttribute('font-size',21);label.textContent=i+1;group.append(label);});const [cx,cy]=map(cm),circle=root.querySelector('[data-rg]');circle.setAttribute('cx',cx);circle.setAttribute('cy',cy);circle.setAttribute('r',95*rg);root.querySelector('[data-com]').setAttribute('d',`M${cx-10} ${cy}H${cx+10}M${cx} ${cy-10}V${cy+10}`);const lab=root.querySelector('[data-com-label]'),mapped=pts.map(map),obstacles=mapped.flatMap(([x,y],i)=>[[x-18,y-18,x+18,y+18],[x+10,(i===2?y+29:y-13)-23,x+33,(i===2?y+29:y-13)+5]]),candidates=[[60,-30],[95,-30],[135,-30],[60,45],[95,45],[135,45],[180,-30],[180,45]].map(([x,y])=>[cx+x,cy+y]).concat([[740,85]]);const chosen=candidates.find(([x,y])=>x>30&&x+65<875&&y>35&&y<490&&!obstacles.some(b=>x-5<b[2]&&x+65>b[0]&&y-25<b[3]&&y+7>b[1]))||[740,85];lab.setAttribute('x',chosen[0]);lab.setAttribute('y',chosen[1]);lab.setAttribute('text-anchor','start');let leader=root.querySelector('[data-com-leader]');if(!leader){leader=document.createElementNS(ns,'path');leader.setAttribute('data-com-leader','');leader.setAttribute('stroke','#a5532e');leader.setAttribute('stroke-width','1.5');leader.setAttribute('fill','none');root.querySelector('svg').insertBefore(leader,lab);}const dx=chosen[0]-8-cx,dy=chosen[1]-8-cy,d=Math.hypot(dx,dy);leader.setAttribute('d',`M${cx+14*dx/d} ${cy+14*dy/d}L${chosen[0]-8} ${chosen[1]-8}`);root.querySelector('[data-answer]').textContent='Re = '+re.toFixed(4)+' Å; X = '+end[0].toFixed(4)+' Å; Rg = '+rg.toFixed(4)+' Å; Lc = 4.0000 Å. '+(en?'The dashed circle shows the mass-weighted radius of gyration.':'虚线圆显示质量加权回转半径。');}fold.addEventListener('input',draw);rotation.addEventListener('input',draw);mass.addEventListener('change',draw);root.querySelector('[data-reset]').addEventListener('click',()=>{fold.value='60';rotation.value='0';mass.value='equal';draw();});draw();});